def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Find axis-aligned hollow rectangular outlines, then fill their interior.
    colors=set(x for row in grid for x in row)
    for c in colors:
        for r in range(h):
            for k in range(w):
                if grid[r][k]!=c: continue
                # top-left corner candidates, use extents from contiguous top edge
                for right in range(k+2,w):
                    if grid[r][right]!=c: break
                    if any(grid[r][x]!=c for x in range(k,right+1)): continue
                    for bot in range(r+2,h):
                        if grid[bot][k]!=c: break
                        if grid[bot][right]!=c: continue
                        if all(grid[bot][x]==c for x in range(k,right+1)) and all(grid[y][k]==c and grid[y][right]==c for y in range(r,bot+1)):
                            interior=[grid[y][x] for y in range(r+1,bot) for x in range(k+1,right)]
                            # only fill blank/background interiors
                            if interior and all(v==grid[0][0] for v in interior):
                                fill=7 if (bot-r-1)*(right-k-1)==1 else 2
                                for y in range(r+1,bot):
                                    for x in range(k+1,right): out[y][x]=fill
                            break
    return out
